import numpy as np
import xarray as xr
from satpy.readers.li_base_nc import LiBaseNC

class MockLiBaseNC(LiBaseNC):
    def __init__(self):
        # We need to bypass the real __init__ because it requires filenames and other args
        self.internal_variables = {
            'lat': xr.DataArray([1, 2, 3], name='lat'),
            'lon': xr.DataArray([4, 5, 6], name='lon'),
        }

    def get_variable_search_paths(self, var_paths):
        return var_paths

    def variable_path_exists(self, vpath):
        return False

    def __getitem__(self, key):
        return xr.DataArray([0], name=key)

reader = MockLiBaseNC()
# 'some_lat' ends with 'lat', so it will incorrectly return the 'lat' internal variable.
result = reader.get_measured_variable('some_lat')
print(f"Result for 'some_lat': {result.name}")

if result.name == 'lat':
    print("BUG REPRODUCED: 'some_lat' matched internal variable 'lat'")
    exit(1)
else:
    print("BUG NOT REPRODUCED")
    exit(0)

